// =========================================================
// INDEXEDDB - NATIVE WRAPPER
//
// Không cần package "idb".
// API bên dưới giữ tương thích với baseService.js và
// schemaService.js hiện tại:
//
//   db.count(table)
//   db.getAll(table)
//   db.add(table, data)
//   db.put(table, data)
//   db.delete(table, key)
//   db.clear(table)
//   db.transaction(table, mode)
//   tx.objectStore(table).getAll()
//   tx.objectStore(table).get(key)
//   tx.done
// =========================================================

const DB_NAME = 'cafe-db3'
const DB_VERSION = 1

let dbPromise = null


// =========================================================
// REQUEST -> PROMISE
// =========================================================

function requestToPromise(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result)
    request.onerror = () => reject(
      request.error || new Error('IndexedDB request error')
    )
  })
}


// =========================================================
// TRANSACTION DONE
// =========================================================

function transactionDone(tx) {
  return new Promise((resolve, reject) => {
    tx.oncomplete = () => resolve()

    tx.onabort = () => reject(
      tx.error || new Error('IndexedDB transaction aborted')
    )

    tx.onerror = () => reject(
      tx.error || new Error('IndexedDB transaction error')
    )
  })
}


// =========================================================
// WRAP OBJECT STORE
// =========================================================

function wrapStore(store) {
  return {
    get keyPath() {
      return store.keyPath
    },

    get autoIncrement() {
      return store.autoIncrement
    },

    get indexNames() {
      return store.indexNames
    },

    getAll() {
      return requestToPromise(store.getAll())
    },

    get(key) {
      return requestToPromise(store.get(key))
    },

    count() {
      return requestToPromise(store.count())
    },

    add(value) {
      return requestToPromise(store.add(value))
    },

    put(value) {
      return requestToPromise(store.put(value))
    },

    delete(key) {
      return requestToPromise(store.delete(key))
    },

    clear() {
      return requestToPromise(store.clear())
    }
  }
}


// =========================================================
// WRAP TRANSACTION
// =========================================================

function wrapTransaction(tx) {
  const done = transactionDone(tx)

  return {
    objectStore(name) {
      return wrapStore(tx.objectStore(name))
    },

    done
  }
}


// =========================================================
// RUN SIMPLE STORE REQUEST
// =========================================================

async function runStoreRequest(
  nativeDb,
  tableName,
  mode,
  action
) {
  const tx = nativeDb.transaction(tableName, mode)
  const done = transactionDone(tx)
  const store = tx.objectStore(tableName)

  const result = await requestToPromise(
    action(store)
  )

  await done

  return result
}


// =========================================================
// WRAP DATABASE
// =========================================================

function wrapDB(nativeDb) {
  return {
    get objectStoreNames() {
      return nativeDb.objectStoreNames
    },

    transaction(storeNames, mode = 'readonly') {
      return wrapTransaction(
        nativeDb.transaction(storeNames, mode)
      )
    },

    count(tableName) {
      return runStoreRequest(
        nativeDb,
        tableName,
        'readonly',
        store => store.count()
      )
    },

    getAll(tableName) {
      return runStoreRequest(
        nativeDb,
        tableName,
        'readonly',
        store => store.getAll()
      )
    },

    get(tableName, key) {
      return runStoreRequest(
        nativeDb,
        tableName,
        'readonly',
        store => store.get(key)
      )
    },

    add(tableName, value) {
      return runStoreRequest(
        nativeDb,
        tableName,
        'readwrite',
        store => store.add(value)
      )
    },

    put(tableName, value) {
      return runStoreRequest(
        nativeDb,
        tableName,
        'readwrite',
        store => store.put(value)
      )
    },

    delete(tableName, key) {
      return runStoreRequest(
        nativeDb,
        tableName,
        'readwrite',
        store => store.delete(key)
      )
    },

    clear(tableName) {
      return runStoreRequest(
        nativeDb,
        tableName,
        'readwrite',
        store => store.clear()
      )
    },

    close() {
      nativeDb.close()
    }
  }
}


// =========================================================
// CREATE / UPGRADE DATABASE
// =========================================================

function openNativeDB() {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === 'undefined') {
      reject(
        new Error('Trình duyệt không hỗ trợ IndexedDB')
      )
      return
    }

    const request = indexedDB.open(
      DB_NAME,
      DB_VERSION
    )

    request.onupgradeneeded = () => {
      const db = request.result

      // ===== TABLE Ban =====
      /*
      if (!db.objectStoreNames.contains('Ban')) {
        const store = db.createObjectStore('Ban', {
          keyPath: 'Id',
          autoIncrement: true
        })

        store.add({
          Ten: 'Ban so 1',
          CoKhach: false,
          Tien: 10000,
          NgayMua: new Date(),
          LoaiNX: 'N',
          Tp: 'QN',
          MonId: 1,
          Loai: 'admin'
        })
      }
      */

      // ===== TABLE HoaDon =====
      if (!db.objectStoreNames.contains('HoaDon')) {
        const store = db.createObjectStore('HoaDon', {
          keyPath: 'Id',
          autoIncrement: true
        })

        store.add({
          KhachId: '001',
          Ngay: new Date()
        })
      }

      // ===== TABLE Khach =====
      if (!db.objectStoreNames.contains('Khach')) {
        const store = db.createObjectStore('Khach', {
          keyPath: 'Id',
          autoIncrement: true
        })

        store.add({
          MaKhach: '',
          Ten: 'Nguyen Van A'
        })
      }

      // ===== TABLE GiaPha =====
      if (!db.objectStoreNames.contains('GiaPha')) {
        const store = db.createObjectStore('GiaPha', {
          keyPath: 'Id',
          autoIncrement: true
        })

        store.add({
          Ten: 'Gia Phả ...',
          Ngay: new Date()
        })
      }

      // ===== TABLE GiaPhaCT =====
      if (!db.objectStoreNames.contains('GiaPhaCT')) {
        const store = db.createObjectStore('GiaPhaCT', {
          keyPath: 'Id',
          autoIncrement: true
        })

        store.add({
          Ten: 'Ba',
          MoTa: 'Mo ta',
          ThuTu: 1,
          PId: 0,
          GiaPhaId: 0
        })
      }

      // ===== TABLE Mon =====
      // ===== TABLE HocSinh =====
      // ===== TABLE HangHoa =====
      // ===== TABLE DonViTinh =====
    }

    request.onsuccess = () => {
      const nativeDb = request.result

      nativeDb.onversionchange = () => {
        nativeDb.close()
        dbPromise = null
      }

      resolve(
        wrapDB(nativeDb)
      )
    }

    request.onerror = () => {
      reject(
        request.error || new Error('Không mở được IndexedDB')
      )
    }

    request.onblocked = () => {
      console.warn(
        'IndexedDB đang bị chặn bởi một tab khác. Hãy đóng các tab cũ rồi thử lại.'
      )
    }
  })
}


// =========================================================
// EXPORT
// =========================================================

export function getDB() {
  if (!dbPromise) {
    dbPromise = openNativeDB()
  }

  return dbPromise
}
